  static float Label(Rect rect,string text,int size,Color color,float spacing=0,bool caption=false){var font=caption?Resources.Load<Font>("Art/fonts/Cinzel-400"):NativeSilverHellUi.Font();font=NativeSilverHellUi.TextFont(font,text);var style=new GUIStyle(GUI.skin.label){font=font,fontSize=size,fontStyle=FontStyle.Normal,wordWrap=false,padding=new RectOffset(),margin=new RectOffset(),alignment=TextAnchor.MiddleCenter};style.normal.textColor=color;if(spacing==0){NativeSilverHellUi.Label(rect,text,style);return style.CalcSize(new GUIContent(text)).x;}float width=0;foreach(char c in text)width+=style.CalcSize(new GUIContent(c.ToString())).x+spacing;width-=spacing;float x=rect.center.x-width/2;foreach(char c in text){var str=c.ToString();float w=style.CalcSize(new GUIContent(str)).x;NativeSilverHellUi.Label(new Rect(x,rect.y,w,rect.height),str,style);x+=w+spacing;}return width;}
